-- This file is NOT a real migration: it becomes one only when the approvals recorded in PACKAGE.json are given and the package is promoted AS A WHOLE, in order.

-- DRAFT E1 — NOT APPLIED, NOT IN packages/db/prisma/migrations. A PROPOSAL for review (Phase 4.7: expenses and other income; ARCHITECTURE.md §F.3 / §F.4).
-- Additive only: FOUR new tables, their helper functions, triggers, grants and RLS. NO change to any existing table, no new account, NO posting, NO route, NO
-- permission grant. The application model it must agree with is apps/api/src/modules/expenses/expense-workflow.ts and other-income.ts (pure, tested).
--
-- WHAT IS BUILT (the smallest approval-independent foundation)
--   expense_category — tenant-scoped, configurable; `requiresApproval` defaults to TRUE (fail-closed). NO `account_id`: the expense-category → GL mapping is an
--                      ACCOUNTANT decision and its column is deliberately not created here (it arrives, with its own approval, as a later additive migration).
--   expense          — the §F.3 record and its lifecycle DRAFT → SUBMITTED → APPROVED → PAID (and SUBMITTED → REJECTED; REJECTED and PAID are terminal), with the four
--                      edges enforced IN THE DATABASE, creator ≠ approver (CHECK and trigger), business columns frozen once submitted, and one append-only EVENT per
--                      transition written in the same transaction (immutable audit reference + idempotency).
--   expense_event    — append-only history: who did what, from which status to which, why (a rejection needs a reason), under which Idempotency-Key.
--   other_income     — the §F.4 record, created as a DRAFT and kept there: §F.4 names no status vocabulary and no approval flow, so NO transition exists in the database
--                      (the status CHECK admits only 'DRAFT'; widening it is a later, approved migration).
--
-- WHAT IS DELIBERATELY NOT HERE (each is an owner / accountant decision, listed in the TypeScript models as open decisions)
--   * any account mapping, journal link, posting column or posting trigger (nothing in this file can post, and the tables carry no journal reference);
--   * any link from an expense or income to `cash_movement`: a cash expense tied to a register session records that tie only; EXPENSE remains
--     BLOCKED_PENDING_POLICY in the cash-movement classification, so NOTHING here moves drawer cash. A non-cash expense can never reference a session (CHECK);
--     manual income has no session column at all;
--   * the PAYABLE payment method: ARCHITECTURE §F.3 lists it, but accounts payable is a Phase 5 boundary — the CHECK REFUSES it rather than pretend it is implemented;
--   * approval thresholds / auto-approval, tax inclusion or tax codes beyond a stored label, resubmission of a rejected expense, payee foreign keys (suppliers arrive
--     with Phase 5; `payeeId` is a plain reference);
--   * the `documents` receipt attachment (no documents table exists yet).
--
-- LESSONS APPLIED FROM DRAFT Z1: (a) every table's access is EXPLICIT — REVOKE ALL from PUBLIC and both application roles, then exactly the grants below (the Phase 1
-- default privileges give flower_app / flower_platform SELECT, INSERT, UPDATE, DELETE on every new table and must not decide the matrix); (b) a TRUNCATE trigger on every
-- table (row triggers cannot see it); (c) every refusal is proven on a disposable database, including the redundant layers (CHECK vs trigger).
--
-- ACTIVATION COUPLING: none with the frozen schema. Companion changes NOT made here: Prisma models + the schema-drift ratchet entries, the repositories / services /
-- routes (all disabled until approved), the permission grants to roles (the keys expense:* / income:* exist and are granted to no system role), the structural-pin
-- amendments. Rollback: DROP the four tables and the fn_p47_* / fn_expense_* / fn_other_income_* functions (safe while no row exists; afterwards the rows are evidence).

-- ══════════════ 0. helpers ══════════════
CREATE FUNCTION fn_p47_user_in_tenant(u UUID, t UUID) RETURNS BOOLEAN AS $$
  SELECT EXISTS (SELECT 1 FROM "user" x WHERE x."id" = u AND x."tenantId" = t);
$$ LANGUAGE sql STABLE;

CREATE FUNCTION fn_p47_no_delete() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION '% is never deleted (id=%)', TG_TABLE_NAME, OLD."id";
END;
$$ LANGUAGE plpgsql;

CREATE FUNCTION fn_p47_no_truncate() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION '% is append-only / never truncated', TG_TABLE_NAME;
END;
$$ LANGUAGE plpgsql;

-- ══════════════ 1. expense_category ══════════════
CREATE TABLE "expense_category" (
    "id"               UUID NOT NULL DEFAULT uuidv7(),
    "tenantId"         UUID NOT NULL,
    "nameEn"           TEXT NOT NULL,
    "nameAr"           TEXT,
    -- fail-closed default: every category needs approval until someone decides otherwise (and the workflow has no auto-approval anyway)
    "requiresApproval" BOOLEAN NOT NULL DEFAULT TRUE,
    "active"           BOOLEAN NOT NULL DEFAULT TRUE,
    "createdAt"        TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt"        TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "expense_category_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "expense_category_name_chk" CHECK (length(btrim("nameEn")) BETWEEN 1 AND 120),
    CONSTRAINT "expense_category_name_ar_chk" CHECK ("nameAr" IS NULL OR length(btrim("nameAr")) BETWEEN 1 AND 120)
);
CREATE UNIQUE INDEX "expense_category_tenant_id_key" ON "expense_category"("tenantId", "id");
CREATE UNIQUE INDEX "expense_category_tenant_name_key" ON "expense_category"("tenantId", lower(btrim("nameEn")));
ALTER TABLE "expense_category"
  ADD CONSTRAINT "expense_category_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "tenant"("id") ON UPDATE CASCADE ON DELETE CASCADE;

CREATE FUNCTION fn_expense_category_guard() RETURNS trigger AS $$
BEGIN
  IF NEW."id" <> OLD."id" OR NEW."tenantId" <> OLD."tenantId" OR NEW."createdAt" <> OLD."createdAt" THEN
    RAISE EXCEPTION 'expense_category: identity is immutable (id=%)', OLD."id";
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_expense_category_guard BEFORE UPDATE ON "expense_category" FOR EACH ROW EXECUTE FUNCTION fn_expense_category_guard();
CREATE TRIGGER trg_expense_category_no_delete BEFORE DELETE ON "expense_category" FOR EACH ROW EXECUTE FUNCTION fn_p47_no_delete();
CREATE TRIGGER trg_expense_category_no_truncate BEFORE TRUNCATE ON "expense_category" FOR EACH STATEMENT EXECUTE FUNCTION fn_p47_no_truncate();

-- ══════════════ 2. expense ══════════════
CREATE TABLE "expense" (
    "id"                UUID NOT NULL DEFAULT uuidv7(),
    "tenantId"          UUID NOT NULL,
    "companyId"         UUID NOT NULL,
    "branchId"          UUID NOT NULL,
    -- the terminal / open register session a CASH expense is tied to (both NULL for a back-office expense). The tie records WHERE it was paid; it moves no cash.
    "posTerminalId"     UUID,
    "registerSessionId" UUID,
    "categoryId"        UUID NOT NULL,
    "amountMinor"       BIGINT NOT NULL,
    "currencyCode"      TEXT NOT NULL,
    "currencyExponent"  SMALLINT NOT NULL,
    "taxAmountMinor"    BIGINT,
    "taxCode"           TEXT,
    "paymentMethod"     TEXT NOT NULL,
    "payeeKind"         TEXT NOT NULL,
    "payeeId"           UUID,
    "expenseDate"       DATE NOT NULL,
    "description"       TEXT NOT NULL,
    "reference"         TEXT,
    "status"            TEXT NOT NULL DEFAULT 'DRAFT',
    "createdByUserId"   UUID NOT NULL,
    "approvedByUserId"  UUID,
    "decidedAt"         TIMESTAMPTZ(6),
    -- the Idempotency-Key of the creating request: a replay finds the row, it never creates a second one
    "idempotencyKey"    TEXT NOT NULL,
    "createdAt"         TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt"         TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "expense_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "expense_amount_chk" CHECK ("amountMinor" > 0),
    CONSTRAINT "expense_tax_chk" CHECK ("taxAmountMinor" IS NULL OR "taxAmountMinor" >= 0),
    CONSTRAINT "expense_tax_code_chk" CHECK ("taxCode" IS NULL OR length(btrim("taxCode")) BETWEEN 1 AND 32),
    CONSTRAINT "expense_currency_shape_chk" CHECK ("currencyCode" ~ '^[A-Z]{3}$'),
    CONSTRAINT "expense_exponent_range_chk" CHECK ("currencyExponent" BETWEEN 0 AND 3),
    -- §F.3 lists PAYABLE too; accounts payable is a PHASE 5 boundary, so it is REFUSED here rather than treated as implemented
    CONSTRAINT "expense_payment_method_chk" CHECK ("paymentMethod" IN ('CASH', 'CARD', 'BANK', 'PETTY_CASH')),
    CONSTRAINT "expense_payee_kind_chk" CHECK ("payeeKind" IN ('SUPPLIER', 'STAFF', 'OTHER')),
    CONSTRAINT "expense_description_chk" CHECK (length(btrim("description")) BETWEEN 1 AND 500),
    CONSTRAINT "expense_reference_chk" CHECK ("reference" IS NULL OR length("reference") <= 100),
    CONSTRAINT "expense_status_chk" CHECK ("status" IN ('DRAFT', 'SUBMITTED', 'APPROVED', 'REJECTED', 'PAID')),
    CONSTRAINT "expense_idempotency_key_chk" CHECK (length("idempotencyKey") BETWEEN 1 AND 128),
    -- a register session implies its terminal, and ONLY a cash expense may be tied to a drawer
    CONSTRAINT "expense_drawer_terminal_chk" CHECK ("registerSessionId" IS NULL OR "posTerminalId" IS NOT NULL),
    CONSTRAINT "expense_drawer_cash_chk" CHECK ("registerSessionId" IS NULL OR "paymentMethod" = 'CASH'),
    -- the decision fields agree with the status, always
    CONSTRAINT "expense_decision_shape_chk" CHECK (
      ("status" IN ('DRAFT', 'SUBMITTED') AND "approvedByUserId" IS NULL AND "decidedAt" IS NULL)
      OR ("status" IN ('APPROVED', 'PAID') AND "approvedByUserId" IS NOT NULL AND "decidedAt" IS NOT NULL)
      OR ("status" = 'REJECTED' AND "approvedByUserId" IS NULL AND "decidedAt" IS NOT NULL)),
    -- separation of duties: nobody approves their own expense
    CONSTRAINT "expense_separation_of_duties_chk" CHECK ("approvedByUserId" IS NULL OR "approvedByUserId" <> "createdByUserId")
);
CREATE UNIQUE INDEX "expense_tenant_id_key" ON "expense"("tenantId", "id");
CREATE UNIQUE INDEX "expense_tenant_idempotency_key" ON "expense"("tenantId", "idempotencyKey");
CREATE INDEX "expense_tenantId_branchId_status_date_idx" ON "expense"("tenantId", "branchId", "status", "expenseDate");
CREATE INDEX "expense_tenantId_registerSessionId_idx" ON "expense"("tenantId", "registerSessionId") WHERE "registerSessionId" IS NOT NULL;
ALTER TABLE "expense"
  ADD CONSTRAINT "expense_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "tenant"("id") ON UPDATE CASCADE ON DELETE CASCADE,
  -- the expense's currency MUST equal the company's default currency (never silently relabelled) and be an authoritative (code, exponent) pair
  ADD CONSTRAINT "expense_company_currency_fkey" FOREIGN KEY ("tenantId", "companyId", "currencyCode")
    REFERENCES "company"("tenantId", "id", "defaultCurrency") ON UPDATE RESTRICT ON DELETE NO ACTION,
  ADD CONSTRAINT "expense_currency_pair_fkey" FOREIGN KEY ("currencyCode", "currencyExponent")
    REFERENCES "currency"("code", "exponent") ON UPDATE RESTRICT ON DELETE NO ACTION,
  ADD CONSTRAINT "expense_branch_scope_fkey" FOREIGN KEY ("tenantId", "companyId", "branchId")
    REFERENCES "branch"("tenantId", "companyId", "id") ON UPDATE NO ACTION ON DELETE NO ACTION,
  -- a terminal, when given, belongs to this company AND branch (a NULL terminal skips the key: a back-office expense)
  ADD CONSTRAINT "expense_terminal_scope_fkey" FOREIGN KEY ("tenantId", "companyId", "branchId", "posTerminalId")
    REFERENCES "pos_terminal"("tenantId", "companyId", "branchId", "id") ON UPDATE NO ACTION ON DELETE NO ACTION,
  ADD CONSTRAINT "expense_category_fkey" FOREIGN KEY ("tenantId", "categoryId")
    REFERENCES "expense_category"("tenantId", "id") ON UPDATE NO ACTION ON DELETE NO ACTION,
  ADD CONSTRAINT "expense_creator_fkey" FOREIGN KEY ("createdByUserId") REFERENCES "user"("id") ON UPDATE NO ACTION ON DELETE NO ACTION,
  ADD CONSTRAINT "expense_approver_fkey" FOREIGN KEY ("approvedByUserId") REFERENCES "user"("id") ON UPDATE NO ACTION ON DELETE NO ACTION;

-- ── 2a. references the foreign keys cannot prove: the creator is of THIS tenant, the category is active, the register session matches scope AND currency and is
--        unresolved (the user table has no (tenantId, id) key and register_session no key on this column set; this migration alters no existing table) ──
CREATE FUNCTION fn_expense_assert_creator(e "expense") RETURNS void AS $$
BEGIN
  IF NOT fn_p47_user_in_tenant(e."createdByUserId", e."tenantId") THEN
    RAISE EXCEPTION 'expense: the creator does not exist in this tenant' USING ERRCODE = 'check_violation';
  END IF;
END;
$$ LANGUAGE plpgsql;

CREATE FUNCTION fn_expense_assert_category(e "expense") RETURNS void AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM "expense_category" c WHERE c."id" = e."categoryId" AND c."tenantId" = e."tenantId" AND c."active") THEN
    RAISE EXCEPTION 'expense: category % is not active in this tenant', e."categoryId" USING ERRCODE = 'check_violation';
  END IF;
END;
$$ LANGUAGE plpgsql;

CREATE FUNCTION fn_expense_assert_session(e "expense") RETURNS void AS $$
DECLARE
  st TEXT;
BEGIN
  IF e."registerSessionId" IS NULL THEN
    RETURN;
  END IF;
  SELECT s."status" INTO st FROM "register_session" s
   WHERE s."id" = e."registerSessionId" AND s."tenantId" = e."tenantId" AND s."companyId" = e."companyId" AND s."branchId" = e."branchId"
     AND s."posTerminalId" = e."posTerminalId" AND s."currencyCode" = e."currencyCode" AND s."currencyExponent" = e."currencyExponent";
  IF NOT FOUND THEN
    RAISE EXCEPTION 'expense: register_session % does not match the expense scope / terminal / currency', e."registerSessionId" USING ERRCODE = 'check_violation';
  END IF;
  IF st = 'CLOSED' THEN
    RAISE EXCEPTION 'expense: register_session % is CLOSED', e."registerSessionId" USING ERRCODE = 'check_violation';
  END IF;
END;
$$ LANGUAGE plpgsql;

-- ── 2b. creation: always a DRAFT ──
CREATE FUNCTION fn_expense_insert_guard() RETURNS trigger AS $$
BEGIN
  IF NEW."status" <> 'DRAFT' OR NEW."approvedByUserId" IS NOT NULL OR NEW."decidedAt" IS NOT NULL THEN
    RAISE EXCEPTION 'expense: an expense is created as a DRAFT with no decision' USING ERRCODE = 'check_violation';
  END IF;
  PERFORM fn_expense_assert_creator(NEW);
  PERFORM fn_expense_assert_category(NEW);
  PERFORM fn_expense_assert_session(NEW);
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_expense_insert_guard BEFORE INSERT ON "expense" FOR EACH ROW EXECUTE FUNCTION fn_expense_insert_guard();

-- ── 2c. the lifecycle: the four edges, frozen business columns once submitted, nothing else changes in a transition ──
CREATE FUNCTION fn_expense_update_guard() RETURNS trigger AS $$
BEGIN
  IF NEW."id" <> OLD."id" OR NEW."tenantId" <> OLD."tenantId" OR NEW."companyId" <> OLD."companyId" OR NEW."branchId" <> OLD."branchId"
     OR NEW."createdByUserId" <> OLD."createdByUserId" OR NEW."idempotencyKey" <> OLD."idempotencyKey" OR NEW."createdAt" <> OLD."createdAt" THEN
    RAISE EXCEPTION 'expense: identity is immutable (id=%)', OLD."id";
  END IF;

  IF NEW."status" = OLD."status" THEN
    IF OLD."status" <> 'DRAFT' THEN
      -- SUBMITTED, APPROVED, REJECTED and PAID are FROZEN: not a single column but updatedAt may change
      IF (to_jsonb(NEW) - 'updatedAt') <> (to_jsonb(OLD) - 'updatedAt') THEN
        RAISE EXCEPTION 'expense %: a % expense is frozen (only a status transition may change it)', OLD."id", OLD."status" USING ERRCODE = 'check_violation';
      END IF;
    ELSE
      -- a DRAFT may be edited; changed references are re-proven
      IF NEW."categoryId" <> OLD."categoryId" THEN PERFORM fn_expense_assert_category(NEW); END IF;
      IF NEW."registerSessionId" IS DISTINCT FROM OLD."registerSessionId" OR NEW."posTerminalId" IS DISTINCT FROM OLD."posTerminalId"
         OR NEW."currencyCode" <> OLD."currencyCode" OR NEW."currencyExponent" <> OLD."currencyExponent" THEN
        PERFORM fn_expense_assert_session(NEW);
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  -- a status change: only the four edges, and NOTHING but the status and the decision fields changes
  IF NOT ((OLD."status", NEW."status") IN (('DRAFT', 'SUBMITTED'), ('SUBMITTED', 'APPROVED'), ('SUBMITTED', 'REJECTED'), ('APPROVED', 'PAID'))) THEN
    RAISE EXCEPTION 'expense %: illegal status transition % -> %', OLD."id", OLD."status", NEW."status" USING ERRCODE = 'check_violation';
  END IF;
  IF (to_jsonb(NEW) - 'updatedAt' - 'status' - 'approvedByUserId' - 'decidedAt') <> (to_jsonb(OLD) - 'updatedAt' - 'status' - 'approvedByUserId' - 'decidedAt') THEN
    RAISE EXCEPTION 'expense %: a transition changes only the status and the decision fields', OLD."id" USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."status" = 'PAID' AND (NEW."approvedByUserId" IS DISTINCT FROM OLD."approvedByUserId" OR NEW."decidedAt" IS DISTINCT FROM OLD."decidedAt") THEN
    RAISE EXCEPTION 'expense %: paying an expense does not change its decision', OLD."id" USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."status" = 'APPROVED' AND NOT fn_p47_user_in_tenant(NEW."approvedByUserId", NEW."tenantId") THEN
    RAISE EXCEPTION 'expense %: the approver does not exist in this tenant', OLD."id" USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_expense_update_guard BEFORE UPDATE ON "expense" FOR EACH ROW EXECUTE FUNCTION fn_expense_update_guard();
CREATE TRIGGER trg_expense_no_delete BEFORE DELETE ON "expense" FOR EACH ROW EXECUTE FUNCTION fn_p47_no_delete();
CREATE TRIGGER trg_expense_no_truncate BEFORE TRUNCATE ON "expense" FOR EACH STATEMENT EXECUTE FUNCTION fn_p47_no_truncate();

-- ══════════════ 3. expense_event: append-only history, one row per transition, in the SAME transaction ══════════════
CREATE TABLE "expense_event" (
    "id"             UUID NOT NULL DEFAULT uuidv7(),
    "tenantId"       UUID NOT NULL,
    "companyId"      UUID NOT NULL,
    "branchId"       UUID NOT NULL,
    "expenseId"      UUID NOT NULL,
    -- 1-based, contiguous per expense (the guard enforces "previous + 1" under the expense row lock)
    "seq"            INTEGER NOT NULL,
    "action"         TEXT NOT NULL,
    "fromStatus"     TEXT,
    "toStatus"       TEXT NOT NULL,
    -- the AUTHENTICATED user who acted (never a caller-supplied attribution)
    "actorUserId"    UUID NOT NULL,
    "reason"         TEXT,
    "idempotencyKey" TEXT NOT NULL,
    -- the transaction the event was written in: the expense row must carry the matching change in the SAME transaction (checked at commit)
    "txId"           BIGINT NOT NULL DEFAULT txid_current(),
    "createdAt"      TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "expense_event_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "expense_event_seq_chk" CHECK ("seq" >= 1),
    CONSTRAINT "expense_event_edge_chk" CHECK (
      ("action" = 'CREATE' AND "fromStatus" IS NULL AND "toStatus" = 'DRAFT')
      OR ("action" = 'SUBMIT' AND "fromStatus" = 'DRAFT' AND "toStatus" = 'SUBMITTED')
      OR ("action" = 'APPROVE' AND "fromStatus" = 'SUBMITTED' AND "toStatus" = 'APPROVED')
      OR ("action" = 'REJECT' AND "fromStatus" = 'SUBMITTED' AND "toStatus" = 'REJECTED')
      OR ("action" = 'PAY' AND "fromStatus" = 'APPROVED' AND "toStatus" = 'PAID')),
    -- a rejection always says why
    CONSTRAINT "expense_event_reason_chk" CHECK (
      ("action" = 'REJECT' AND "reason" IS NOT NULL AND length(btrim("reason")) BETWEEN 1 AND 500)
      OR ("action" <> 'REJECT' AND ("reason" IS NULL OR length("reason") <= 500))),
    CONSTRAINT "expense_event_idempotency_key_chk" CHECK (length("idempotencyKey") BETWEEN 1 AND 128)
);
CREATE UNIQUE INDEX "expense_event_expense_seq_key" ON "expense_event"("tenantId", "expenseId", "seq");
CREATE UNIQUE INDEX "expense_event_idempotency_key" ON "expense_event"("tenantId", "idempotencyKey");
CREATE INDEX "expense_event_tenantId_branchId_createdAt_idx" ON "expense_event"("tenantId", "branchId", "createdAt");
ALTER TABLE "expense_event"
  ADD CONSTRAINT "expense_event_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "tenant"("id") ON UPDATE CASCADE ON DELETE CASCADE,
  ADD CONSTRAINT "expense_event_expense_fkey" FOREIGN KEY ("tenantId", "expenseId") REFERENCES "expense"("tenantId", "id") ON UPDATE NO ACTION ON DELETE NO ACTION,
  ADD CONSTRAINT "expense_event_actor_fkey" FOREIGN KEY ("actorUserId") REFERENCES "user"("id") ON UPDATE NO ACTION ON DELETE NO ACTION;

CREATE FUNCTION fn_expense_event_guard() RETURNS trigger AS $$
DECLARE
  ex   RECORD;
  lst  RECORD;
BEGIN
  -- the expense row is the serialisation point of its workflow: concurrent transitions queue here, and the loser then sees the winner's event
  SELECT e."companyId", e."branchId", e."createdByUserId" INTO ex
    FROM "expense" e WHERE e."id" = NEW."expenseId" AND e."tenantId" = NEW."tenantId" FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'expense_event: expense % not found', NEW."expenseId";
  END IF;
  IF NEW."companyId" <> ex."companyId" OR NEW."branchId" <> ex."branchId" THEN
    RAISE EXCEPTION 'expense_event: scope does not match the expense' USING ERRCODE = 'check_violation';
  END IF;
  NEW."txId" := txid_current(); -- never caller-supplied
  SELECT v."seq", v."toStatus" INTO lst FROM "expense_event" v WHERE v."expenseId" = NEW."expenseId" AND v."tenantId" = NEW."tenantId" ORDER BY v."seq" DESC LIMIT 1;
  IF NOT FOUND THEN
    IF NEW."seq" <> 1 OR NEW."action" <> 'CREATE' THEN
      RAISE EXCEPTION 'expense_event: the first event of an expense is its CREATE with seq 1' USING ERRCODE = 'check_violation';
    END IF;
  ELSE
    IF NEW."seq" <> lst."seq" + 1 THEN
      RAISE EXCEPTION 'expense_event: seq must be % (got %)', lst."seq" + 1, NEW."seq" USING ERRCODE = 'check_violation';
    END IF;
    IF NEW."fromStatus" IS DISTINCT FROM lst."toStatus" THEN
      RAISE EXCEPTION 'expense_event: the expense is % — an event cannot start from %', lst."toStatus", NEW."fromStatus" USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF NOT fn_p47_user_in_tenant(NEW."actorUserId", NEW."tenantId") THEN
    RAISE EXCEPTION 'expense_event: the actor does not exist in this tenant' USING ERRCODE = 'check_violation';
  END IF;
  -- separation of duties: nobody approves or rejects their own expense
  IF NEW."action" IN ('APPROVE', 'REJECT') AND NEW."actorUserId" = ex."createdByUserId" THEN
    RAISE EXCEPTION 'expense_event: separation of duties — the creator cannot %', lower(NEW."action") USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_expense_event_guard BEFORE INSERT ON "expense_event" FOR EACH ROW EXECUTE FUNCTION fn_expense_event_guard();

CREATE FUNCTION fn_expense_event_append_only() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'expense_event is append-only: % is never permitted (id=%)', TG_OP, OLD."id";
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_expense_event_append_only BEFORE UPDATE OR DELETE ON "expense_event" FOR EACH ROW EXECUTE FUNCTION fn_expense_event_append_only();
CREATE TRIGGER trg_expense_event_no_truncate BEFORE TRUNCATE ON "expense_event" FOR EACH STATEMENT EXECUTE FUNCTION fn_p47_no_truncate();

-- ── 3a. every expense row / transition has its event, written in the SAME transaction (checked at COMMIT) ──
CREATE FUNCTION fn_expense_requires_event() RETURNS trigger AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NOT EXISTS (SELECT 1 FROM "expense_event" v WHERE v."expenseId" = NEW."id" AND v."tenantId" = NEW."tenantId" AND v."seq" = 1 AND v."action" = 'CREATE'
                      AND v."actorUserId" = NEW."createdByUserId" AND v."txId" = txid_current()) THEN
      RAISE EXCEPTION 'expense %: created without its CREATE event in the same transaction', NEW."id" USING ERRCODE = 'check_violation';
    END IF;
  ELSE
    IF NOT EXISTS (SELECT 1 FROM "expense_event" v WHERE v."expenseId" = NEW."id" AND v."tenantId" = NEW."tenantId" AND v."fromStatus" = OLD."status"
                      AND v."toStatus" = NEW."status" AND v."txId" = txid_current()
                      AND (NEW."status" <> 'APPROVED' OR v."actorUserId" = NEW."approvedByUserId")) THEN
      RAISE EXCEPTION 'expense %: % -> % has no matching event (by the approver, for an approval) in the same transaction', NEW."id", OLD."status", NEW."status" USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NULL;
END;
$$ LANGUAGE plpgsql;
CREATE CONSTRAINT TRIGGER trg_expense_created_has_event AFTER INSERT ON "expense" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_expense_requires_event();
CREATE CONSTRAINT TRIGGER trg_expense_transition_has_event AFTER UPDATE ON "expense" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW
  WHEN (OLD."status" IS DISTINCT FROM NEW."status") EXECUTE FUNCTION fn_expense_requires_event();

-- ── 3b. and the reverse: an event can never be written WITHOUT the matching change of its expense (the expense's status at commit is the last event's target) ──
CREATE FUNCTION fn_expense_event_matches_status() RETURNS trigger AS $$
DECLARE
  cur     TEXT;
  last_to TEXT;
BEGIN
  SELECT e."status" INTO cur FROM "expense" e WHERE e."id" = NEW."expenseId" AND e."tenantId" = NEW."tenantId";
  SELECT v."toStatus" INTO last_to FROM "expense_event" v WHERE v."expenseId" = NEW."expenseId" AND v."tenantId" = NEW."tenantId" ORDER BY v."seq" DESC LIMIT 1;
  IF cur IS DISTINCT FROM last_to THEN
    RAISE EXCEPTION 'expense_event %: the expense is % but its latest event says %', NEW."id", cur, last_to USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END;
$$ LANGUAGE plpgsql;
CREATE CONSTRAINT TRIGGER trg_expense_event_matches_status AFTER INSERT ON "expense_event" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_expense_event_matches_status();

-- ══════════════ 4. other_income (DRAFT only until the approval flow is decided) ══════════════
CREATE TABLE "other_income" (
    "id"               UUID NOT NULL DEFAULT uuidv7(),
    "tenantId"         UUID NOT NULL,
    "companyId"        UUID NOT NULL,
    "branchId"         UUID NOT NULL,
    -- the credit side: an OTHER_INCOME account of THIS company (§F.4). Which account is an open decision; that it is not revenue is not.
    "accountId"        UUID NOT NULL,
    "amountMinor"      BIGINT NOT NULL,
    "currencyCode"     TEXT NOT NULL,
    "currencyExponent" SMALLINT NOT NULL,
    "taxAmountMinor"   BIGINT,
    -- §F.4 posts `Dr Cash/Bank`: the only two settlement methods named. NO register-session column exists: manual income never reaches a drawer here.
    "paymentMethod"    TEXT NOT NULL,
    "sourceReference"  TEXT,
    "incomeDate"       DATE NOT NULL,
    "description"      TEXT NOT NULL,
    -- §F.4 names a status but no vocabulary and no approval flow: the ONLY value admitted is DRAFT; widening it is a later, approved migration
    "status"           TEXT NOT NULL DEFAULT 'DRAFT',
    "createdByUserId"  UUID NOT NULL,
    "idempotencyKey"   TEXT NOT NULL,
    "createdAt"        TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt"        TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "other_income_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "other_income_amount_chk" CHECK ("amountMinor" > 0),
    CONSTRAINT "other_income_tax_chk" CHECK ("taxAmountMinor" IS NULL OR "taxAmountMinor" >= 0),
    CONSTRAINT "other_income_currency_shape_chk" CHECK ("currencyCode" ~ '^[A-Z]{3}$'),
    CONSTRAINT "other_income_exponent_range_chk" CHECK ("currencyExponent" BETWEEN 0 AND 3),
    CONSTRAINT "other_income_payment_method_chk" CHECK ("paymentMethod" IN ('CASH', 'BANK')),
    CONSTRAINT "other_income_description_chk" CHECK (length(btrim("description")) BETWEEN 1 AND 500),
    CONSTRAINT "other_income_reference_chk" CHECK ("sourceReference" IS NULL OR length("sourceReference") <= 100),
    CONSTRAINT "other_income_status_chk" CHECK ("status" = 'DRAFT'),
    CONSTRAINT "other_income_idempotency_key_chk" CHECK (length("idempotencyKey") BETWEEN 1 AND 128)
);
CREATE UNIQUE INDEX "other_income_tenant_id_key" ON "other_income"("tenantId", "id");
CREATE UNIQUE INDEX "other_income_tenant_idempotency_key" ON "other_income"("tenantId", "idempotencyKey");
CREATE INDEX "other_income_tenantId_branchId_date_idx" ON "other_income"("tenantId", "branchId", "incomeDate");
ALTER TABLE "other_income"
  ADD CONSTRAINT "other_income_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "tenant"("id") ON UPDATE CASCADE ON DELETE CASCADE,
  ADD CONSTRAINT "other_income_company_currency_fkey" FOREIGN KEY ("tenantId", "companyId", "currencyCode")
    REFERENCES "company"("tenantId", "id", "defaultCurrency") ON UPDATE RESTRICT ON DELETE NO ACTION,
  ADD CONSTRAINT "other_income_currency_pair_fkey" FOREIGN KEY ("currencyCode", "currencyExponent")
    REFERENCES "currency"("code", "exponent") ON UPDATE RESTRICT ON DELETE NO ACTION,
  ADD CONSTRAINT "other_income_branch_scope_fkey" FOREIGN KEY ("tenantId", "companyId", "branchId")
    REFERENCES "branch"("tenantId", "companyId", "id") ON UPDATE NO ACTION ON DELETE NO ACTION,
  ADD CONSTRAINT "other_income_account_fkey" FOREIGN KEY ("tenantId", "companyId", "accountId")
    REFERENCES "account"("tenantId", "companyId", "id") ON UPDATE NO ACTION ON DELETE NO ACTION,
  ADD CONSTRAINT "other_income_creator_fkey" FOREIGN KEY ("createdByUserId") REFERENCES "user"("id") ON UPDATE NO ACTION ON DELETE NO ACTION;

CREATE FUNCTION fn_other_income_guard() RETURNS trigger AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW."id" <> OLD."id" OR NEW."tenantId" <> OLD."tenantId" OR NEW."companyId" <> OLD."companyId" OR NEW."branchId" <> OLD."branchId"
       OR NEW."createdByUserId" <> OLD."createdByUserId" OR NEW."idempotencyKey" <> OLD."idempotencyKey" OR NEW."createdAt" <> OLD."createdAt" THEN
      RAISE EXCEPTION 'other_income: identity is immutable (id=%)', OLD."id";
    END IF;
  ELSIF NOT fn_p47_user_in_tenant(NEW."createdByUserId", NEW."tenantId") THEN
    RAISE EXCEPTION 'other_income: the creator does not exist in this tenant' USING ERRCODE = 'check_violation';
  END IF;
  -- the credit side must be an OTHER_INCOME account — never revenue, never any other category (system sales revenue is never entered here)
  IF TG_OP = 'INSERT' OR NEW."accountId" <> OLD."accountId" THEN
    IF NOT EXISTS (SELECT 1 FROM "account" a WHERE a."id" = NEW."accountId" AND a."tenantId" = NEW."tenantId" AND a."companyId" = NEW."companyId"
                      AND a."category" = 'OTHER_INCOME') THEN
      RAISE EXCEPTION 'other_income: account % is not an OTHER_INCOME account of this company', NEW."accountId" USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_other_income_guard BEFORE INSERT OR UPDATE ON "other_income" FOR EACH ROW EXECUTE FUNCTION fn_other_income_guard();
CREATE TRIGGER trg_other_income_no_delete BEFORE DELETE ON "other_income" FOR EACH ROW EXECUTE FUNCTION fn_p47_no_delete();
CREATE TRIGGER trg_other_income_no_truncate BEFORE TRUNCATE ON "other_income" FOR EACH STATEMENT EXECUTE FUNCTION fn_p47_no_truncate();

-- ══════════════ 5. EXPLICIT grants + Row-Level Security ══════════════
-- The Phase 1 ALTER DEFAULT PRIVILEGES grants SELECT, INSERT, UPDATE, DELETE to flower_app AND flower_platform on every new table. EVERYTHING is revoked first and exactly
-- the grants below are given back: they are the ONLY access. No role ever holds DELETE or TRUNCATE; the event table holds no UPDATE either.
GRANT ALL ON "expense_category", "expense", "expense_event", "other_income" TO flower_migrate;
REVOKE ALL ON "expense_category", "expense", "expense_event", "other_income" FROM PUBLIC, flower_platform, flower_app;
GRANT SELECT, INSERT, UPDATE ON "expense_category", "expense", "other_income" TO flower_platform, flower_app;
GRANT SELECT, INSERT ON "expense_event" TO flower_platform, flower_app;

-- categories are tenant-wide (no branch dimension)
ALTER TABLE "expense_category" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "expense_category_tenant_isolation" ON "expense_category"
  USING ("tenantId" = nullif(current_setting('app.tenant_id', true), '')::uuid)
  WITH CHECK ("tenantId" = nullif(current_setting('app.tenant_id', true), '')::uuid);
ALTER TABLE "expense_category" FORCE ROW LEVEL SECURITY;

-- the branch-scoped tables: tenant + the branch GUC defence in depth (same shape as cash_movement)
ALTER TABLE "expense" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "expense_tenant_branch_isolation" ON "expense"
  USING ("tenantId" = nullif(current_setting('app.tenant_id', true), '')::uuid
         AND (nullif(current_setting('app.branch_id', true), '') IS NULL OR "branchId" = nullif(current_setting('app.branch_id', true), '')::uuid))
  WITH CHECK ("tenantId" = nullif(current_setting('app.tenant_id', true), '')::uuid
         AND (nullif(current_setting('app.branch_id', true), '') IS NULL OR "branchId" = nullif(current_setting('app.branch_id', true), '')::uuid));
ALTER TABLE "expense" FORCE ROW LEVEL SECURITY;

ALTER TABLE "expense_event" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "expense_event_tenant_branch_isolation" ON "expense_event"
  USING ("tenantId" = nullif(current_setting('app.tenant_id', true), '')::uuid
         AND (nullif(current_setting('app.branch_id', true), '') IS NULL OR "branchId" = nullif(current_setting('app.branch_id', true), '')::uuid))
  WITH CHECK ("tenantId" = nullif(current_setting('app.tenant_id', true), '')::uuid
         AND (nullif(current_setting('app.branch_id', true), '') IS NULL OR "branchId" = nullif(current_setting('app.branch_id', true), '')::uuid));
ALTER TABLE "expense_event" FORCE ROW LEVEL SECURITY;

ALTER TABLE "other_income" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "other_income_tenant_branch_isolation" ON "other_income"
  USING ("tenantId" = nullif(current_setting('app.tenant_id', true), '')::uuid
         AND (nullif(current_setting('app.branch_id', true), '') IS NULL OR "branchId" = nullif(current_setting('app.branch_id', true), '')::uuid))
  WITH CHECK ("tenantId" = nullif(current_setting('app.tenant_id', true), '')::uuid
         AND (nullif(current_setting('app.branch_id', true), '') IS NULL OR "branchId" = nullif(current_setting('app.branch_id', true), '')::uuid));
ALTER TABLE "other_income" FORCE ROW LEVEL SECURITY;
